"use client";

import { useRouter, useParams } from "next/navigation";
import { useState, useEffect, useCallback } from "react";
import { Formik, Form, Field, ErrorMessage, FormikProps } from "formik";
import * as Yup from "yup";
import { useMutation, useQuery } from "@tanstack/react-query";
import { toast, ToastContainer } from "react-toastify";
import Select from "react-select";
import { Product, Category, ProductStatus } from "@/types/product";
import axiosInstance from "@/utils/axiosInstance";
import { updateProduct, fetchProduct, fetchCategories } from "@/components/product/api";
import AccessDenied from "@/components/common/AccessDenied";

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams() as { productId: string };

  const [initialValues, setInitialValues] = useState<Partial<Product>>({
    productName: "",
    detail: "",
    price: 0,
    weight: 0,
    productCategory: "",
  });

  const { data: product, isLoading: isProductLoading } = useQuery<Product>({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const { data: categories, isLoading: isCategoriesLoading } = useQuery<Category[]>({
    queryKey: ["categories"],
    queryFn: fetchCategories,
  });

  const [isUnauthorized, setIsUnauthorized] = useState(false);

  useEffect(() => {
    if (product) {
      if (product.status !== ProductStatus.DRAFT) {
        console.warn("Unauthorized access: Redirecting to /403...");
        setIsUnauthorized(true);
        setTimeout(() => router.push("/403"), 2000);
        return;
      }

      const matchedCategory = categories?.find((c) => c.categoryName === product.productCategory);

      setInitialValues({
        productName: product.productName || "",
        detail: product.detail || "",
        price: product.price || 0,
        weight: product.weight || 0,
        productCategory: matchedCategory ? String(matchedCategory.categoryId) : "",
      });
    }
  }, [product, categories, router]);

  if (isProductLoading || isCategoriesLoading) return <div>Loading...</div>;

  if (isUnauthorized) return <AccessDenied />;

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <ToastContainer />
      <h2 className="text-3xl text-gray-500 font-semibold mb-4">Edit Product Draft</h2>
      {initialValues.productName ? (
        <ProductForm
          initialValues={initialValues}
          categories={categories || []}
          productId={productId}
        />
      ) : (
        <div>Loading product details...</div>
      )}
    </div>
  );
};

const ProductForm = ({ initialValues, categories, productId }: any) => {
  const mutation = useMutation({
    mutationFn: (values: Partial<Product>) => updateProduct({ productId, values }),
    onSuccess: () => toast.success("Product updated successfully!"),
    onError: (error) => {
      toast.error("Failed to update product.");
      console.error(error);
    },
  });

  const formatInputValue = (value: any) => {
    const stringValue = String(value || 0);
    const numericValue = stringValue.replace(/\D/g, "");
    if (numericValue === "") return "0";
    return Number(numericValue).toLocaleString("id-ID");
  };

  return (
    <Formik
      initialValues={initialValues}
      validationSchema={Yup.object({
        productName: Yup.string()
          .min(3, "Product name must be at least 3 characters long")
          .required("Required")
          .test("not-draft", "Product name cannot be 'Draft Product'", (value: string | undefined) => value !== "Draft Product"),
        detail: Yup.string()
          .min(3, "Details must be at least 3 characters long")
          .required("Required")
          .test("not-draft", "Details cannot be 'This is a draft product.'", (value: string) => value !== "This is a draft product."),
        price: Yup.number()
          .typeError("Price must be a number")
          .positive("Price must be a positive number")
          .required("Required"),
        weight: Yup.number()
          .typeError("Weight must be a number")
          .positive("Weight must be a positive number")
          .required("Required"),
        productCategory: Yup.string().required("Category is required"),
      })}
      onSubmit={(values) => {
        const formattedValues = {
          ...values,
          categoryId: values.productCategory ? Number(values.productCategory) : undefined,
        };
        delete formattedValues.productCategory;
        console.log("Sending data to API:", formattedValues);
        mutation.mutate(formattedValues);
      }}
    >
      {({ values, setFieldValue, isSubmitting, isValid }) => (
        <Form className="space-y-4">
          <div>
            <label className="block text-gray-500">Product Name</label>
            <Field
              type="text"
              name="productName"
              className="border p-2 rounded w-1/2 text-gray-500"
            />
            <ErrorMessage name="productName" component="div" className="text-red-500" />
          </div>

          <div>
            <label className="block text-gray-500">Details</label>
            <Field
              type="text"
              name="detail"
              className="border p-2 rounded w-1/2 text-gray-500"
            />
            <ErrorMessage name="detail" component="div" className="text-red-500" />
          </div>

          <div>
            <label className="block text-gray-500">Price</label>
            <Field name="price">
              {({ field, form }: any) => (
                <div className="flex items-center">
                  <span className="mr-2 text-gray-500">Rp.</span>
                  <input
                    {...field}
                    type="text"
                    className="border p-2 rounded w-1/3 text-gray-500"
                    value={field.value ? formatInputValue(field.value) : ""}
                    onChange={(e) => {
                      const formattedValue = formatInputValue(e.target.value);
                      form.setFieldValue("price", formattedValue.replace(/\D/g, ""));
                    }}
                  />
                </div>
              )}
            </Field>
            <ErrorMessage name="price" component="div" className="text-red-500" />
          </div>

          <div>
            <label className="block text-gray-500">Weight</label>
            <div className="flex items-center">
              <Field name="weight">
                {({ field, form }: any) => (
                  <div className="flex items-center">
                    <input
                      {...field}
                      type="text"
                      className="border p-2 rounded w-1/3 text-gray-500"
                      value={field.value ? formatInputValue(field.value) : ""}
                      onChange={(e) => {
                        const formattedValue = formatInputValue(e.target.value);
                        form.setFieldValue("weight", formattedValue.replace(/\D/g, ""));
                      }}
                    />
                    <span className="ml-2 text-gray-500">grams</span>
                  </div>
                )}
              </Field>
            </div>
            <ErrorMessage name="weight" component="div" className="text-red-500" />
          </div>

          <div>
            <label className="block text-gray-500">Product Category</label>
            <Select
              options={categories?.map((category: { categoryId: any; categoryName: any; }) => ({
                value: category.categoryId,
                label: category.categoryName,
              }))}
              value={
                categories
                  ?.map((category: { categoryId: any; categoryName: any; }) => ({
                    value: category.categoryId,
                    label: category.categoryName,
                  }))
                  .find((option: { value: number; }) => option.value === Number(values.productCategory)) || null
              }
              onChange={(selectedOption) =>
                setFieldValue("productCategory", selectedOption?.value || "")
              }
              className="border p-2 rounded w-1/2 text-gray-500"
              placeholder="Search category..."
            />
            <ErrorMessage name="productCategory" component="div" className="text-red-500" />
          </div>

          <div className="mt-6">
            <h3 className="text-xl text-gray-500 font-semibold mb-2">Product Images</h3>
            <ProductImageUploader productId={productId} />
          </div>

          <button
            type="submit"
            disabled={isSubmitting || !isValid}
            className={`mt-4 px-4 py-2 text-white bg-blue-500 rounded ${isSubmitting || !isValid ? "opacity-50 cursor-not-allowed" : ""}`}
          >
            Update Product
          </button>
        </Form>
      )}
    </Formik>
  );
};

const ProductImageUploader = ({ productId }: any) => {
  const [images, setImages] = useState<{ position: number; productPictureUrl: string | null; pictureId: number | null }[]>([]);
  const [loading, setLoading] = useState<{ [key: number]: boolean }>({});
  const [fetching, setFetching] = useState<boolean>(false);

  const fetchImages = useCallback(async () => {
    setFetching(true);
    try {
      const response = await axiosInstance.get(`/pictures/${productId}`);
      const updatedImages = [1, 2, 3].map((position) =>
        response.data.data.find((img: any) => img.position === position) || {
          pictureId: null,
          productPictureUrl: null,
          position,
        }
      );
      setImages(updatedImages);
    } catch (error) {
      console.error("Failed to load images", error);
    } finally {
      setFetching(false);
    }
  }, [productId]);

  useEffect(() => {
    fetchImages();
  }, [fetchImages]);

  const handleUpload = async (position: number, file: File) => {
    setLoading((prev) => ({ ...prev, [position]: true }));
    try {
      const formData = new FormData();
      formData.append("file", file);

      await axiosInstance.post(`/pictures/${productId}/${position}/upload`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      toast.success(`Picture ${position} uploaded successfully!`);
      await fetchImages();
    } catch (error) {
      toast.error("Failed to upload picture");
      console.error(error);
    } finally {
      setLoading((prev) => ({ ...prev, [position]: false }));
    }
  };

  const handleFileChange = (position: number, event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      const file = event.target.files[0];
      handleUpload(position, file);
    }
  };

  return (
    <div className="flex space-x-4">
      {images.map((image) => (
        <div key={image.position} className="w-24 h-24 border p-2">
          {image.productPictureUrl ? (
            <img src={image.productPictureUrl} alt={`Product image ${image.position}`} className="w-full h-full object-cover" />
          ) : (
            <div className="text-center">No image</div>
          )}
          <input
            type="file"
            onChange={(e) => handleFileChange(image.position, e)}
            disabled={loading[image.position]}
            className="mt-2"
          />
        </div>
      ))}
    </div>
  );
};

export default EditDraftProduct;
